export function GladiatorMelee(self: EdictT): void {
  const aim = vec3(MELEE_DISTANCE, self.mins[0], -4);
  if (fire_hit(self, aim, irandom(20, 25), 300)) {
    gi.sound(self, SoundchanT.CHAN_AUTO, sound_cleaver_hit, 1, ATTN_NORM, 0);
  } else {
    gi.sound(self, SoundchanT.CHAN_AUTO, sound_cleaver_miss, 1, ATTN_NORM, 0);
    self.monsterinfo.melee_debounce_time = Gtime_add(level.time, Gtime_from_sec(1.5));
  }
}

