// ---------------------------------------------------------------------------
// railgun attack (base gladiator)
// ---------------------------------------------------------------------------

export function GladiatorGun(self: EdictT): void {
  const { forward, right } = angleVectorsFR(self);
  const start = M_ProjectFlashSource(self, monsterFlashOffset()[MonsterMuzzleflashIdT.MZ2_GLADIATOR_RAILGUN_1], forward, right);

  // calc direction to where we targeted
  const dir = vec3_normalized(vec3_sub(self.pos1, start));

  monster_fire_railgun(self, start, dir, 50, 100, MonsterMuzzleflashIdT.MZ2_GLADIATOR_RAILGUN_1);
}

