export const gladiator_move_pain = RegisterMmove("gladiator_move_pain", move(FRAME_pain2, FRAME_pain5, gladiator_frames_pain, gladiator_run));

const gladiator_frames_pain_air: MframeT[] = [frame(ai_move), frame(ai_move), frame(ai_move), frame(ai_move), frame(ai_move)];
export const gladiator_move_pain_air = RegisterMmove("gladiator_move_pain_air", move(FRAME_painup2, FRAME_painup6, gladiator_frames_pain_air, gladiator_run));

export const gladiator_pain: PainFn = RegisterPain("gladiator_pain", (self: EdictT, _other: EdictT, _kick: number, _damage: number, mod: ModT): void => {
  if (level.time < self.pain_debounce_time) {
    if (self.velocity[2] > 100 && self.monsterinfo.active_move === gladiator_move_pain) {
      M_SetAnimation(self, gladiator_move_pain_air, true);
    }
    return;
  }

  self.pain_debounce_time = Gtime_add(level.time, Gtime_from_sec(3));

  if (frandom() < 0.5) gi.sound(self, SoundchanT.CHAN_VOICE, sound_pain1, 1, ATTN_NORM, 0);
  else gi.sound(self, SoundchanT.CHAN_VOICE, sound_pain2, 1, ATTN_NORM, 0);

  if (!M_ShouldReactToPain(self, mod)) return; // no pain anims in nightmare

  if (self.velocity[2] > 100) M_SetAnimation(self, gladiator_move_pain_air, true);
  else M_SetAnimation(self, gladiator_move_pain, true);
});

export const gladiator_setskin = RegisterMonsterinfoSetskin("gladiator_setskin", (self: EdictT): void => {
  if (self.health < self.max_health / 2) self.s.skinnum |= 1;
  else self.s.skinnum &= ~1;
});

