export const gladiator_die: DieFn = RegisterDie(
  "gladiator_die",
  (self: EdictT, _inflictor: EdictT, _attacker: EdictT, damage: number, _point: Vec3, mod: ModT): void => {
    // check for gib
    if (M_CheckGib(self, mod)) {
      gi.sound(self, SoundchanT.CHAN_VOICE, gi.soundindex("misc/udeath.wav"), 1, ATTN_NORM, 0);

      self.s.skinnum = Math.trunc(self.s.skinnum / 2);

      ThrowGibs(self, damage, [
        { count: 2, gibname: "models/objects/gibs/bone/tris.md2" },
        { count: 2, gibname: "models/objects/gibs/sm_meat/tris.md2" },
        { count: 2, gibname: "models/monsters/gladiatr/gibs/thigh.md2", type: GibTypeT.GIB_SKINNED },
        { gibname: "models/monsters/gladiatr/gibs/larm.md2", type: GibTypeT.GIB_SKINNED | GibTypeT.GIB_UPRIGHT },
        { gibname: "models/monsters/gladiatr/gibs/rarm.md2", type: GibTypeT.GIB_SKINNED | GibTypeT.GIB_UPRIGHT },
        { gibname: "models/monsters/gladiatr/gibs/chest.md2", type: GibTypeT.GIB_SKINNED },
        { gibname: "models/monsters/gladiatr/gibs/head.md2", type: GibTypeT.GIB_SKINNED | GibTypeT.GIB_HEAD },
      ]);
      self.deadflag = true;
      return;
    }

    if (self.deadflag) return;

    // regular death
    gi.sound(self, SoundchanT.CHAN_BODY, sound_die, 1, ATTN_NORM, 0);

    if (brandom()) gi.sound(self, SoundchanT.CHAN_VOICE, sound_die2, 1, ATTN_NORM, 0);

    self.deadflag = true;
    self.takedamage = true;

    M_SetAnimation(self, gladiator_move_death, true);
  },
);

